  "console.memory.observed": "Last observed {when}",
  "console.memory.times": {
    one: "Observed once",
    other: "Observed {count} times"
  },
  "console.memory.unfindable": "Kept, but recall can never choose it: this entry has no searchable form.",
  "console.memory.show": "What it says",
  "console.memory.refused.role": "Your role cannot set memories aside in this company.",
  "console.memory.forget": "Forget this",
  "console.memory.forgotten": "Set aside. It will not be used in an answer again.",
  "console.memory.set-aside": {
    one: "Set aside: {count}. It is never used in an answer.",
    other: "Set aside: {count}. They are never used in an answer."
  },
  "console.memory.erase": "Forgetting is not erasure. The record that this company once believed a fact stays in the audit trail, and your account page holds the export and erasure controls.",
  "console.memory.refused": "Refused at {gate}. You may not set memories aside in this company.",
  "console.memory.unknown": "That entry is no longer here. The list has been read again.",
