  "site.os.window.evidence": "Evidence",
  "site.os.proposal.headline": "Pause the campaign feeding the impaired funnel",
  // Fixed demo copy, not a computed runtime value, so no placeholder.
  "site.os.proposal.body": "Cost per trial rose 212% over six days while conversion held flat.",
  "site.os.admission.body": "Five of the eight, in order. The order is a security property, not a style choice.",
  // Northwind is the demo company's name, left inline (not a placeholder) sinc
