  "console.voice.waiting": "Il y en a {count} qui vous attendent.",
  "console.voice.nothing-waiting": "Rien ne vous attend.",
  "console.voice.address.informal": "Entendu. Je te tutoie a partir de maintenant.",
  "console.voice.address.formal": "Entendu. Je vous vouvoie a partir de maintenant.",
  "console.voice.unclear": "Cela n\u2019est pas pass\xE9 clairement, donc rien n\u2019a \xE9t\xE9 consign\xE9. Dites approuver ou refuser et le num\xE9ro.",
  "console.voice.confirm": "Le num\xE9ro {ordinal} est {objective}. Dites oui pour consigner cette d\xE9cision, ou non pour la laisser ouverte.",
  "console.voice.approved": "Consign\xE9 comme approuv\xE9.",
  "console.voice.refused": "Consign\xE9 comme refus\xE9.",
